def _as_context(context):
    """The past as a DataFrame: one row per time step, one column per series.

    A list or NumPy array has no time labels, so its rows are labelled 0, 1,
    2, ... and its columns ``y`` (one series) or 0, 1, ... (several series).
    """
    if isinstance(context, pd.DataFrame):
        return context
    if isinstance(context, pd.Series):
        return context.to_frame(name=context.name if context.name is not None else "y")
    if isinstance(context, (list, tuple, np.ndarray)):
        values = np.asarray(context)
        if values.ndim == 1:
            return pd.DataFrame({"y": values})
        if values.ndim == 2:
            return pd.DataFrame(values)
    raise TypeError(
        "context must be a pandas DataFrame or Series, a list, or a one- or two-dimensional "
        "NumPy array"
    )


def _one_value_per_step(values, names):
    """Read one value per step as one row per step when there is a single series."""
    try:
        array = np.asarray(values)
    except (TypeError, ValueError):
        return values  # ragged or non-numeric: the output checks report it
    if array.ndim == 1 and names is not None and len(names) == 1:
        return array[:, None]
    return array


def _as_forecast(output, task):
    """Turn whatever the model's ``predict`` returned into a Forecast to check.

    - A list or NumPy array holds one value per step for one series, or one
      row per step and one column per series. Its rows are the requested
      future steps in order and its columns the context's series in order.
    - A pandas DataFrame or Series keeps its own index and column names, so
      wrong dates or a wrong series order still fail their checks. An unnamed
      Series stands for the task's single series.
    - A Forecast is used as given. Without ``target_names`` its series are the
      task's, and a one-dimensional ``point`` for one series is one value per step.
    """
    if isinstance(output, Forecast):
        names = (
            task.target_names if output.target_names is None else output.target_names
        )
        point = output.point
        if point is not None:
            point = _one_value_per_step(point, names)
        if names is output.target_names and point is output.point:
            return output
        return dataclasses.replace(output, point=point, target_names=names)
    if isinstance(output, pd.Series):
        if output.name is None and len(task.target_names) == 1:
            names = task.target_names
        else:
            names = (output.name if output.name is not None else "y",)
        return Forecast(
            output.index, point=output.to_numpy()[:, None], target_names=names
        )
    if isinstance(output, pd.DataFrame):
        return Forecast(
            output.index, point=output.to_numpy(), target_names=tuple(output.columns)
        )
    if isinstance(output, (list, tuple, np.ndarray)):
        return Forecast(
            task.future_index.copy(),
            point=_one_value_per_step(output, task.target_names),
            target_names=task.target_names,
        )
    raise TypeError(
        "model.predict(future_index) must return one value per future step: a list or NumPy "
        "array, a pandas Series or DataFrame indexed by future_index, or a timegym.Forecast; "
        f"got {type(output).__name__}"
    )


def _instance_seeds(seeds, seed, instances, default_instances):
    """Return the case seeds and the seeding record for run metadata.

    With an explicit ``seeds`` list nothing else is derived. Otherwise
    instance ``i`` uses ``seed + i``; ``seed=None`` draws a fresh base seed,
    which is recorded so the run can be repeated.
    """
    if seeds is not None:
        if seed != 0 or instances is not None:
            raise ValueError("Pass either seeds=[...] or seed/instances, not both")
        return [nonnegative_int(value, "seed") for value in seeds], None
    count = positive_int(
        default_instances if instances is None else instances, "instances"
    )
    base = secrets.randbelow(2**31) if seed is None else nonnegative_int(seed, "seed")
    return [base + i for i in range(count)], {"seed": base, "instances": count}


class Pipeline:
    """Evaluate fresh model instances on independent, seeded scenarios.

    Native models implement fit(context) and predict(future_index). The
    context is the past as a DataFrame, one row per time step and one column
    per series (``y`` for one series). ``future_index`` holds the labels of the
    steps to forecast, continuing the context's index. ``predict`` returns one
    value per step: a list or NumPy array (one column per series when there
    are several), a Series or DataFrame indexed by ``future_index``, or a
    Forecast, which can also carry quantiles and samples. Supply a model
    instance (copied before every case), a class, or a model_factory
    producing a fresh unfitted instance.
    sklearn regressors/transformers can be added with add(); ``reduction``
    selects one of REDUCTIONS for them and, like ``window_length``, does not
    change native models. An optional ``target_transform`` is refitted on
    each context before the model and inverted on the forecast it returns.
    """

    def __init__(
        self,
        model=None,
        window_length=12,
        reduction="recursive",
        *,
        model_factory=None,
        target_transform=None,
    ):
        if reduction not in REDUCTIONS:
            raise ValueError(
                f"Unknown reduction {reduction!r}; choose from {REDUCTIONS}"
            )
        protocol = ("clone_unfitted", "fit_transform", "inverse_transform")
        if target_transform is not None and (
            inspect.isclass(target_transform)
            or not all(
                callable(getattr(target_transform, name, None)) for name in protocol
            )
        ):
            raise TypeError(
                "target_transform must be an instance implementing clone_unfitted(), "
                "fit_transform(context) and inverse_transform(forecast)"
            )
        self.model = model
        if model is not None and model_factory is not None:
            raise ValueError("Specify model or model_factory, not both")
        if model_factory is not None and not callable(model_factory):
            raise TypeError(
                "model_factory must be a callable producing a fresh unfitted model"
            )
        self.model_factory = model_factory
        window_length = positive_int(window_length, "window_length")
        self.window_length = int(window_length)
        self.reduction = reduction
        self.target_transform = target_transform
        self.steps = []

    def add(self, estimator, **parameters):
        """Add an sklearn transformer or final regressor; returns self."""
        if self.model is not None or self.model_factory is not None:
            raise ValueError("Use a native model or sklearn steps, not both")
        if inspect.isclass(estimator):
            estimator = estimator(**parameters)
        elif parameters:
            estimator = fresh_model(estimator).set_params(**parameters)
        self.steps.append(estimator)
        return self

    def _model(self, horizon):
        if self.steps:
            return SklearnForecaster(
                self.steps,
                self.window_length,
                reduction=self.reduction,
                horizon=horizon,
            )
        if self.model is None and self.model_factory is None:
            return NaiveForecaster()
        newly_constructed = self.model_factory is not None or inspect.isclass(
            self.model
        )
        candidate = (
            self.model_factory()
            if self.model_factory is not None
            else (self.model() if inspect.isclass(self.model) else self.model)
        )
        if callable(getattr(candidate, "clone_unfitted", None)):
            return candidate if newly_constructed else fresh_model(candidate)
        if is_sklearn_regressor(candidate):
            return SklearnForecaster(
                [candidate],
                self.window_length,
                reduction=self.reduction,
                horizon=horizon,
            )
        return candidate if newly_constructed else fresh_model(candidate)

    def _model_name(self) -> str:
        if self.steps:
            return "SklearnForecaster"
        if self.model_factory is not None:
            return getattr(self.model_factory, "__qualname__", "model_factory")
        if inspect.isclass(self.model):
            return self.model.__name__
        if self.model is not None:
            return type(self.model).__name__
        return "NaiveForecaster"

    def to_config(self):
        """Return JSON-safe configuration and whether safe automatic replay is supported."""
        return pipeline_config(self)

    @classmethod
    def from_config(cls, config):
        """Rebuild allowlisted built-in models and target transforms without dynamic imports."""
        return cls(**pipeline_from_config(config))

    def predict(self, context, future_index):
        """Fit on context and predict the supplied index, without future targets.

        ``context`` is the past: a DataFrame with one column per series, a
        Series, or a list or NumPy array, whose rows are labelled 0, 1, 2, ...
        ``future_index`` is any sequence of the labels to forecast; after a
        list of 120 values the next 12 steps are ``range(120, 132)``.

        A target transform is refitted on this context alone and the model sees
        only the transformed context. A forecast that meets its contract is
        inverted to the original scale; one that violates it is returned
        unchanged, so evaluation reports the model's fault, not the inversion's.
        """
        context = _as_context(context)
        if not isinstance(future_index, pd.Index):
            future_index = pd.Index(future_index)
        # Share the public task contract, including unique target names.
        task = ForecastTask(context=context, future_index=future_index)
        transform = None
        if self.target_transform is not None:
            transform = self.target_transform.clone_unfitted()
            if transform is self.target_transform:
                raise ValueError(
                    "clone_unfitted() must return a new target transform instance"
                )
            task = ForecastTask(
                context=transform.fit_transform(context.copy(deep=True)),
                future_index=future_index,
            )
        model = self._model(len(future_index))
        model.fit(task.context.copy(deep=True))
        forecast = _as_forecast(model.predict(future_index.copy()), task)
        if transform is not None and not forecast.validate(task):
            forecast = transform.inverse_transform(forecast)
        return forecast

    def run(
        self,
        scenarios=None,
        seeds=None,
        *,
        seed=0,
        instances=None,
        check_dependence=False,
        n_calibration=99,
        alpha=0.05,
        dependence_seed_offset=100_000,
    ):
        """Evaluate once per case and retain the data, forecast, and diagnostics.

        Each scenario is drawn ``instances`` times (default 3). Instance ``i``
        uses seed ``seed + i`` in every scenario, so scenarios are compared on
        the same random draws. ``seed=None`` picks a fresh base seed and
        records it in ``run.metadata["seed"]``. An explicit ``seeds`` list
        replaces both. ``run.report`` is the usual serializable
        ``TestReport``; ``run.plot_forecasts()`` and ``run.plot_errors()``
        inspect these exact outputs without additional fitting.
        """
        if self.steps:
            SklearnForecaster(self.steps, self.window_length)
        settings = diagnostic_settings(
            check_dependence=check_dependence,
            n_calibration=n_calibration,
            alpha=alpha,
            dependence_seed_offset=dependence_seed_offset,
        )
        seeds, seeding = _instance_seeds(seeds, seed, instances, 3)
        if scenarios is None:
            scenarios = default_scenarios()
        scenarios = list(scenarios)
        if not scenarios or not seeds:
            raise ValueError("Provide at least one scenario and one seed")
        results = []
        for scenario_index, scenario in enumerate(scenarios):
            for seed_index, case_seed in enumerate(seeds):
                case = scenario.generate(seed=case_seed)
                forecast = None
                try:
                    forecast = self.predict(case.task.context, case.task.future_index)
                    result = evaluate_forecast(
                        case,
                        forecast,
                        check_dependence=check_dependence,
                        dependence_seed=int(case_seed) + dependence_seed_offset,
                        n_calibration=n_calibration,
                        alpha=alpha,
                    )
                except Exception as exc:
                    result = CaseResult(
                        scenario=scenario.kind,
                        seed=int(case_seed),
                        diagnostics=[
                            DiagnosticResult(
                                name="model_execution",
                                status="ERROR",
                                category="execution",
                                message=f"{type(exc).__name__}: {exc}",
                                evidence=exception_evidence(exc),
                            )
                        ],
                        metrics={},
                        manifest=case.manifest,
                    )
                results.append(
                    EvaluatedCase(
                        case=case,
                        forecast=forecast,
                        result=result,
                        scenario_index=scenario_index,
                        seed_index=seed_index,
                    )
                )
        config = self.to_config()
        return ForecastRun(
            cases=results,
            metadata={
                **runtime_provenance(),
                "model": self._model_name(),
                "window_length": self.window_length,
                "reduction": self.reduction,
                "target_transform": config["target_transform"],
                "pipeline_config": config,
                "diagnostic_settings": settings,
                **(seeding or {}),
            },
        )

    def test(
        self,
        scenarios=None,
        seeds=None,
        *,
        seed=0,
        instances=None,
        check_dependence=False,
        n_calibration=99,
        alpha=0.05,
        dependence_seed_offset=100_000,
    ):
        """Evaluate each scenario on each instance and return a TestReport.

        Seeds work as in ``run``: instance ``i`` uses ``seed + i``.
        """
        return self.run(
            scenarios,
            seeds=seeds,
            seed=seed,
            instances=instances,
            check_dependence=check_dependence,
            n_calibration=n_calibration,
            alpha=alpha,
            dependence_seed_offset=dependence_seed_offset,
        ).report

    def scorecard(
        self,
        patterns=None,
        *,
        noise_levels=2,
        instances=10,
        seed=0,
        context_length=120,
        horizon=24,
        title=None,
    ):
        """Score the model on a grid of patterns and noise levels; returns a Scorecard.

        Rows are patterns from ``timegym.PATTERNS`` (all ten by default) and
        columns are noise levels from low to high. Each cell is drawn
        ``instances`` times with seeds ``seed + i``, the same draws in every
        cell. A cell's score is ``100 * unavoidable / (unavoidable + avoidable)``
        mean squared error, pooled over its instances; instances that crash or
        fail an output check score zero. ``score_low`` to ``score_high`` in the
        table is a 95% percentile bootstrap interval over the cell's series; with
        ten series it is rough and tends to be too narrow, so raise ``instances``
        to tighten it. ``seed=None`` picks a fresh seed, kept on the result.
        """
        from timegym.scorecard import _scorecard

        return _scorecard(
            self,
            patterns,
            noise_levels=noise_levels,
            instances=instances,
            seed=seed,
            context_length=context_length,
            horizon=horizon,
            title=title,
        )

    def plot_tests(
        self,
        scenarios=None,
        seeds=None,
        *,
        seed=0,
        instances=None,
        show_quantiles=False,
        figsize=None,
        history=None,
        **diagnostic_settings,
    ):
        """Fit a display suite and return its forecast matrix Figure.

        Display defaults use 240 context observations and 80 forecast steps;
        ``test`` and ``run`` keep their defaults of 120 context rows and 12
        steps. To make several figures from the same fits, use ``run`` and its
        plot methods.
        """
        _deprecated(
            "Pipeline.plot_tests", "use Pipeline.run(...).plot_forecasts() instead"
        )
        if scenarios is None:
            scenarios = default_scenarios(context_length=240, horizon=80)
        return self.run(
            scenarios,
            seeds=seeds,
            seed=seed,
            instances=instances,
            **diagnostic_settings,
        ).plot_forecasts(
            show_quantiles=show_quantiles, figsize=figsize, history=history
        )

    def plot_errors(
        self,
        scenarios=None,
        seeds=None,
        *,
        seed=0,
        instances=None,
        metric="mean_reference_mse",
        bins=None,
        missing="raise",
        figsize=None,
        **diagnostic_settings,
    ):
        """Fit once per requested case and plot the retained score distribution.

        This convenience call draws 20 instances by default. Use an existing
        run's ``plot_errors`` method to inspect previously evaluated forecasts.
        """
        _deprecated(
            "Pipeline.plot_errors", "use Pipeline.run(...).plot_errors() instead"
        )
        if seeds is None and instances is None:
            instances = 20
        return self.run(
            scenarios,
            seeds=seeds,
            seed=seed,
            instances=instances,
            **diagnostic_settings,
        ).plot_errors(metric=metric, bins=bins, missing=missing, figsize=figsize)


